import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import { GoogleGenAI } from "@google/genai";
import dotenv from "dotenv";

dotenv.config();

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json());

  // Unified API Route for AI analysis (supports Gemini and local Ollama)
  const aiAnalyzeHandler = async (req: express.Request, res: express.Response): Promise<any> => {
    try {
      const { prompt, provider = "gemini", ollamaUrl, model = "gemma2:2b" } = req.body;
      
      if (provider === "ollama") {
        // Build Ollama URL: request body > env > fallback default
        const targetOllamaHost = ollamaUrl || process.env.OLLAMA_HOST || "http://127.0.0.1:11434";
        const cleanHost = targetOllamaHost.replace(/\/$/, ""); // trim trailing slash
        const modelToUse = model || process.env.OLLAMA_MODEL || "gemma2:2b";

        console.log(`[AI-LOCAL] Requesting Ollama generation. Host: ${cleanHost}, Model: ${modelToUse}`);

        try {
          // Since Ollama can take a few seconds on CPU, let's configure fetch
          const controller = new AbortController();
          const timeoutId = setTimeout(() => controller.abort(), 60000); // 60s timeout

          const response = await fetch(`${cleanHost}/api/generate`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              model: modelToUse,
              prompt: prompt,
              stream: false
            }),
            signal: controller.signal
          });

          clearTimeout(timeoutId);

          if (!response.ok) {
            throw new Error(`Servidor Ollama respondió con código ${response.status}`);
          }

          const data: any = await response.json();
          return res.json({ 
            text: data.response || `No se recibió respuesta válida del modelo ${modelToUse}.`,
            provider: "ollama",
            model: modelToUse,
            host: cleanHost
          });
        } catch (ollamaErr: any) {
          console.error("Local Ollama Error:", ollamaErr);
          
          let alertMsg = `❌ **Error de conexión con IA Local (Ollama)**\n\n`;
          alertMsg += `No pudimos establecer comunicación con el servidor Ollama en: \`${cleanHost}\`.\n\n`;
          alertMsg += `**Siga estos sencillos pasos para habilitarlo en su entorno o clúster Antigravity:**\n`;
          alertMsg += `1. Asegúrese de que Ollama esté corriendo en su máquina (\`ollama serve\` o la aplicación de escritorio).\n`;
          alertMsg += `2. **Importante (CORS):** Para habilitar peticiones desde el navegador o contenedores proxy, configure la variable de entorno de Ollama: \`OLLAMA_ORIGINS=* o OLLAMA_ORIGINS="http://localhost:3000,http://127.0.0.1:3000"\`.\n`;
          alertMsg += `3. Descargue el modelo liviano recomendado ejecutando en su terminal:\n   \`ollama pull ${modelToUse}\`\n`;
          alertMsg += `4. Alternativamente, intente usar la dirección IP de su máquina en lugar de \`localhost\` si está corriendo este servidor en un contenedor virtualizado (ej. \`http://host.docker.internal:11434\` o una IP de red local).\n\n`;
          alertMsg += `*Detalle técnico:* ${ollamaErr.message || "Timeout / Connection Refused"}`;

          // Resolve gracefully so the UI can display this setup instruction beautifuly!
          return res.json({ text: alertMsg, isConfigureInstructions: true });
        }
      }

      // Fallback/Default to Gemini Cloud API
      const apiKey = process.env.GEMINI_API_KEY;
      
      if (!apiKey) {
        return res.status(200).json({ 
          text: "⚠️ **Llave de API (GEMINI_API_KEY) no configurada.**\n\nPor favor, en AI Studio configure su API Key de Gemini de manera segura en **Settings > Secrets**, o cambie al **Motor de IA Local (Ollama)** en las opciones superiores de este panel para usar modelos fuera de línea compatibles con Antigravity (estilo Gemma, Llama o Qwen)." 
        });
      }

      const ai = new GoogleGenAI({ 
        apiKey: apiKey,
        httpOptions: {
          headers: {
            'User-Agent': 'aistudio-build'
          }
        }
      });

      const response = await ai.models.generateContent({
        model: 'gemini-3.5-flash',
        contents: prompt,
      });

      res.json({ text: response.text || "", provider: "gemini" });
    } catch (err: any) {
      console.error("Gemini Error:", err);
      res.status(500).json({ error: err.message || "Error al procesar la solicitud con Gemini" });
    }
  };

  app.post("/api/analyze", aiAnalyzeHandler);
  app.post("/api/gemini", aiAnalyzeHandler);

  // Serve static assets in production or mount Vite in development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on port ${PORT}`);
  });
}

startServer();
